-- =====================================================================
-- Blackwing Descent Downport  --  19  Server-side spell_dbc (REQUIRED)
-- ---------------------------------------------------------------------
-- Downports Cata 4.3.4 spell ids that BWD content references in
-- smart_scripts action_type 11 (SMART_ACTION_CAST) and creature_addon.auras
-- but that were never added to acore_world.spell_dbc:
--  - 31 ids for 01_creature_templates.sql's SmartAI trash (Pyrecraw 42764,
--    Ivoroc 42767, Maimgor 42768, Golem Sentry 42800, Drakonid Slayer 42802,
--    Drakeadon Mongrel 46083) -- SmartAIMgr::LoadFromDB rejected every one of
--    those cast actions at boot ("uses non-existent Spell entry N, skipped"),
--    leaving all 6 packs with zero usable abilities.
--  - 3 ids (78173/78494/78495) for creature_addon rows (guids 9555149-9555151)
--    whose static auras failed to apply ("has wrong spell N defined in auras
--    field in creature_addon").
-- This fork's worldserver loads spells from acore_world.spell_dbc (a 234-col
-- runtime table), NOT just the client Spell.dbc -- without these rows the
-- server cannot cast/resolve them. Add matching Custom/CSV DBC/Spell.csv
-- rows separately if these need client-visible tooltips/visuals.
-- Source: k:/tmp/cata-dbc/Spell.dbc + SpellEffect.dbc (build 15601), via
-- Custom/Custom feature SQLs/worlddb/Deepholm/tools/spell_downport.py
-- (same generation path as HyjalCata/53_spell_dbc_additions.sql).
-- =====================================================================

DELETE FROM `spell_dbc` WHERE `ID` IN (78173,78494,78495,79904,79921,80084,80127,80130,80145,80270,80295,80329,80332,80336,80341,80345,80368,80369,80370,80371,80372,80390,80391,80392,81055,81063,91896,91901,91902,91904,91907,91908,91909,95060);

